#!/usr/bin/env bash
# Разовый показ гостю (тестировщику) прогноза рынка авиации: короткая сводка + приглашение в /forecast.
#   bash tester/forecast_demo.sh <TELEGRAM_ID> <день октября> <ЧЧ:ММ>      например: … 328083444 21 11:05
# Задача с cron «M H Д 10 *» сработает снова через год — после показа удалить: openclaw automations delete <id>.
set -euo pipefail
ID="${1:?Telegram ID гостя}"; D="${2:?день}"; T="${3:?время ЧЧ:ММ}"
[[ "$ID" =~ ^[0-9]{5,15}$ ]] || { echo "ID должен быть числом"; exit 1; }
HH=${T%%:*}; MM=${T##*:}
MSG='Покажи пользователю (он тестирует Ави, потенциальный клиент) новую возможность — прогноз рынка авиации. Выполни: cd ~/aviation-monitor && python3 market.py brief. Перескажи в 6–8 строк по guides/market-forecast.md (пункт 1): самолёты, вертолёты, 2–3 новости, которые могут изменить картину, со ссылкой словом «ссылка». Начни с одной строки: «Новое в Ави — прогноз рынка самолётов и вертолётов до 2030 года с учётом новостей». Закончи: «Подробнее — команда /forecast в меню: самолёты, вертолёты, новости, Excel». Прогноз помечай как оценку. Без восклицательных знаков, не длиннее 1200 знаков.'
openclaw automations create "$((10#$MM)) $((10#$HH)) $D 10 *" "$MSG" --name "Гость: прогноз рынка $D.10" \
  --tz Europe/Moscow --agent tester --session isolated --announce --channel telegram --to "$ID" \
  | grep -E '"id"|"name"|"nextRunAtMs"' | head -3
